SELECT pr.record_id, pr.user_id, pr.change_type, pr.points, pr.balance_after,
       pr.source, pr.related_id, pr.remark, pr.created_at, pr.create_by,
       pr.create_time, pr.update_by, pr.update_time,
       u.nick_name
FROM sys_points_record pr
LEFT JOIN sys_user u ON u.user_id = pr.user_id


        AND pr.user_id = #{userId}


        AND pr.change_type = #{changeType}


        AND pr.source = #{source}


        AND DATE(pr.created_at) >= #{startDate}


        AND DATE(pr.created_at) <= #{endDate}


ORDER BY pr.created_at DESC

SELECT COUNT(*)
FROM sys_points_record
WHERE user_id = #{userId}
  AND source = 'AD'
  AND related_id = #{adId}
  AND DATE(created_at) = #{date}

SELECT COUNT(*)
FROM sys_points_record
WHERE user_id = #{userId}
  AND source = 'AD'
  AND DATE(created_at) = #{date}
